def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(range(10), key=lambda x: sum(row.count(x) for row in g))

    # Find same-color 4-connected components.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                        (ny, nx) not in seen and g[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            comps.append((color, cells))

    # Look for a long, thin L-shaped guide with a clear elbow.
    guides = []
    for color, cells in comps:
        s = set(cells)
        for r, c in cells:
            for dr in (-1, 1):
                for dc in (-1, 1):
                    a = 0
                    while (r + (a + 1) * dr, c) in s:
                        a += 1
                    b = 0
                    while (r, c + (b + 1) * dc) in s:
                        b += 1
                    if a >= 2 and b >= 2:
                        # Favor the longest pair of perpendicular arms.
                        guides.append((a * b, color, cells, r, c, dr, dc))

    if not guides:
        return g

    _, guide_color, guide_cells, er, ec, arm_r, arm_c = max(
        guides, key=lambda item: item[0]
    )
    guide_set = set(guide_cells)

    # The target lies in the quadrant opposite the two arms.
    qdr, qdc = -arm_r, -arm_c
    choices = []
    for color, cells in comps:
        if color == guide_color and set(cells) == guide_set:
            continue
        in_quadrant = [
            (r, c) for r, c in cells
            if (r - er) * qdr > 0 and (c - ec) * qdc > 0
        ]
        if in_quadrant:
            dist = min((r - er) ** 2 + (c - ec) ** 2
                       for r, c in in_quadrant)
            choices.append((dist, cells))

    if choices:
        _, target = min(choices, key=lambda item: item[0])
        for r, c in target:
            g[r][c] = guide_color
    return g
